% test call by nameclcclearaddpath([pwd,'\testy'])% inputsa = 1;b = 2;c = 3;argIn = {a,b,c};% namesn1 = 'f1';n2 = 'f2';n3 = 'f3';n4 = 'f4';% experssions% evalf1()feval(n1)f2(1,2,3)feval(n2,argIn{:})f3()[txt,outStruct]=evalc([n3,'()'])f4(1,2,3)[txt,outStruct]=evalc([n4,'(argIn{:})'])%% Bridge testdisp('test "fBridge" direct calling+++++++++++++++++++++++++++++++++++++++++++')fBridge4('f1',0,0)jPas = cell();jPas{1} = a;jPas{2} = b;jPas{3} = c;jSon = jsonencode(jPas);fBridge4('f2',1,0,jPas)fBridge4('f3',0,1)fBridge4('f4',1,1,jPas)disp('call fBridge4 from system commandLine-----------------------------------')% quiet + noGUI + noHistory + noWindow + noInitRC%cmdstr = 'fBridge4.m "f1" 0 0';% tested%cmdstr = "fBridge4('f1',0,0)";% testedoctBase 	= 	'octave-cli';% invoke & optionsoctOpts 	= 	'-q -G -H -W -f';funcPath	= 	'E:\Dropbox\PROJECT\Lipido\ocTool\Bridge\testy\';BridgeName = 	'fBridge4';funcName 	=  "'f1'";hasInput = 	0;hasOutput = 	0;sysCmd = sprintf('%s %s -p %s -e "%s(%s,%d,%d)"',octBase,octOpts,funcPath,BridgeName,funcName,hasInput,hasOutput)if isunix()	[status, output] = unix(sysCmd)elseif ispc()  [status, output] = dos(sysCmd)else	[stat_id out_str] = system(sysCmd,true,'sync')	error('os detection failed')enddisp('fBridge5 CALL from CMD==================================================')% quiet + noGUI + noHistory + noWindow + noInitRC%cmdstr = 'fBridge4.m "f1" 0 0';% tested%cmdstr = "fBridge4('f1',0,0)";% testedoctBase 	= 	'octave-cli';% invoke & optionsoctOpts 	= 	'-q -G -H -W -f';funcPath	= 	'E:\Dropbox\PROJECT\Lipido\ocTool\Bridge\testy\';BridgeName = 	'fBridge5';funcName 	=  "'f1'";sysCmd = sprintf('%s %s -p %s -e "%s(%s)"',octBase,octOpts,funcPath,BridgeName,funcName)if isunix()	[status, output] = unix(sysCmd)elseif ispc()  [status, output] = dos(sysCmd)else	[stat_id out_str] = system(sysCmd,true,'sync')	error('os detection failed')end